import sys
from collections import deque

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return

    tokens = line.split()
    nodes = []
    i = 0
    while i < len(tokens):
        val = int(tokens[i])
        child_val = int(tokens[i + 1])
        direction = tokens[i + 2]
        nodes.append((val, child_val, direction))
        i += 3

    if not nodes:
        return

    parent_to_children = {}
    all_vals = set()

    for val, child_val, direction in nodes:
        all_vals.add(val)
        all_vals.add(child_val)
        if val not in parent_to_children:
            parent_to_children[val] = []
        parent_to_children[val].append((child_val, direction))

    root = None
    for val in all_vals:
        if val not in parent_to_children:
            root = val
            break

    if root is None:
        return

    result = []
    queue = deque([root])
    left_to_right = True

    while queue:
        level_size = len(queue)
        level_nodes = []

        for _ in range(level_size):
            node = queue.popleft()
            level_nodes.append(node)

            if node in parent_to_children:
                children = parent_to_children[node]
                for child_val, direction in children:
                    queue.append(child_val)

        if left_to_right:
            level_nodes.reverse()

        result.extend(level_nodes)
        left_to_right = not left_to_right

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
